-- 파라미터 이름을 틀린다

@Test
void 이름_불일치() {
    try {
        em.createQuery(
                "select m from Member m where m.username = :username",
                Member.class)
            .setParameter("userName", "m1")     // N 이 대문자다
            .getSingleResult();
    } catch (Exception e) {
        System.out.println("예외: " + e.getClass().getSimpleName());
        System.out.println("말:   " + e.getMessage());
    }
}

예외: IllegalArgumentException
