-- 조건을 하나 더 얹는다

@Test
void 조건_둘() {
    System.out.println("--- JPQL ---");
    em.createQuery(
            "select m from Member m" +
            " where m.username = :username and m.age >= :age",
            Member.class)
        .setParameter("username", "m3")
        .setParameter("age", 20)
        .getResultList();

    em.clear();
    System.out.println("--- Querydsl ---");
    queryFactory.selectFrom(member)
            .where(member.username.eq("m3")
                    .and(member.age.goe(20)))
            .fetch();
}

