-- 띄어쓰기를 빠뜨려 본다

@Test
void 띄어쓰기() {
    try {
        em.createQuery(
                "select m from Member m where m.username = :u" +
                "and m.age >= :a", Member.class)      // 앞 공백이 없다
            .setParameter("u", "m1").setParameter("a", 10)
            .getResultList();
    } catch (Exception e) {
        System.out.println("예외: " + e.getClass().getSimpleName());
    }
}

